from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026, 10, 1, tzinfo=timezone.utc)

def mk(status="captured", amt="80.00", refunded="0.00"):
    return Payment("pay_1","inv_1",Decimal(amt),status=status,created_at=T0,captured_at=T0,refunded_amount=Decimal(refunded))

# partial then full
p = mk()
outage_refund(p, Decimal("8.00"), T0)
print("partial:", p.refunded_amount, p.status)
outage_refund(p, Decimal("72.00"), T0)
print("full:", p.refunded_amount, p.status)
print("audit:", [(e["event"], e["amount"], e["refunded_amount"]) for e in audit.events("outage_refund")])

# over-refund
p = mk(refunded="75.00")
try: outage_refund(p, Decimal("10.00"), T0)
except BillingError as e: print("over:", e.code)

# non-captured
try: outage_refund(mk(status="authorized"), Decimal("1.00"), T0)
except BillingError as e: print("state:", e.code)

# non-positive
for a in ("0.00","-1.00"):
    try: outage_refund(mk(), Decimal(a), T0)
    except BillingError as e: print("amount", a, e.code)

# banker's rounding: 0.125 -> 0.12
p = mk(amt="100.00")
outage_refund(p, Decimal("0.125"), T0)
print("round:", p.refunded_amount)

# naive datetime
try: outage_refund(mk(), Decimal("1.00"), datetime(2026,10,1))
except BillingError as e: print("naive:", e.code)
EOF"}

